import { expect, test, type Page, type Route } from '@playwright/test'

const shouldRunBaseline = process.env.UI_UX_BASELINE === '1'
const shouldRunA11ySmoke = process.env.UI_UX_A11Y === '1'
const fixedNow = '2026-07-07T08:30:00.000Z'

type ViewportCase = {
  width: number
  height: number
  label: string
}

type RouteCase = {
  path: string
  label: string
  authenticated: boolean
  readyText: string
}

const VIEWPORTS: ViewportCase[] = [
  { width: 390, height: 844, label: 'mobile-390' },
  { width: 1440, height: 900, label: 'desktop-1440' },
]

const ROUTES: RouteCase[] = [
  { path: '/', label: 'dashboard', authenticated: true, readyText: 'ورود به بازار' },
  { path: '/market', label: 'market', authenticated: true, readyText: 'هیچ لفظ فعالی یافت نشد' },
  { path: '/operations', label: 'operations', authenticated: true, readyText: 'عملیات' },
  { path: '/operations/customers', label: 'customers', authenticated: true, readyText: 'مشتریان' },
  { path: '/operations/accountants', label: 'accountants', authenticated: true, readyText: 'حسابداران' },
  { path: '/account', label: 'account', authenticated: true, readyText: 'پروفایل و تنظیمات' },
  { path: '/profile', label: 'profile', authenticated: true, readyText: 'اطلاعات شخصی' },
  { path: '/account/notifications', label: 'notifications', authenticated: true, readyText: 'هیچ اعلانی یافت نشد' },
  { path: '/admin/users', label: 'admin-users', authenticated: true, readyText: 'مدیریت کاربران' },
  { path: '/admin/commodities', label: 'admin-commodities', authenticated: true, readyText: 'مدیریت کالاها' },
  { path: '/login', label: 'login', authenticated: false, readyText: 'ورود به بازار' },
  { path: '/register', label: 'register', authenticated: false, readyText: 'تکمیل ثبت‌نام' },
  { path: '/i/uiux-baseline', label: 'invite-landing', authenticated: false, readyText: 'دعوت‌نامه اختصاصی' },
]

const CURRENT_USER = {
  id: 9001,
  account_name: 'uiux_visual_user',
  full_name: 'کاربر تست UI',
  role: 'مدیر ارشد',
  account_status: 'active',
  is_accountant: false,
  customer_tier: null,
  has_bot_access: true,
}

function createJwt(payload: Record<string, unknown>) {
  const header = Buffer.from(JSON.stringify({ alg: 'none', typ: 'JWT' })).toString('base64url')
  const body = Buffer.from(JSON.stringify(payload)).toString('base64url')
  return `${header}.${body}.uiux`
}

async function installDeterministicRuntime(page: Page) {
  await page.addInitScript((nowIso) => {
    const fixedTime = new Date(nowIso).valueOf()
    const NativeDate = Date

    class FixedDate extends NativeDate {
      constructor(...args: ConstructorParameters<typeof Date>) {
        if (args.length === 0) {
          super(fixedTime)
        } else {
          super(...args)
        }
      }

      static now() {
        return fixedTime
      }
    }

    Object.setPrototypeOf(FixedDate, NativeDate)
    globalThis.Date = FixedDate as DateConstructor

    const style = document.createElement('style')
    style.setAttribute('data-ui-ux-baseline', 'true')
    style.textContent = `
      *, *::before, *::after {
        animation-delay: 0s !important;
        animation-duration: 0s !important;
        animation-iteration-count: 1 !important;
        caret-color: transparent !important;
        scroll-behavior: auto !important;
        transition-delay: 0s !important;
        transition-duration: 0s !important;
      }

      .circle-timer,
      [class*="timer"],
      [data-testid*="timer"],
      [data-testid*="countdown"] {
        visibility: hidden !important;
      }
    `
    document.documentElement.appendChild(style)
  }, fixedNow)
}

async function primeAuthenticatedLayout(page: Page) {
  const token = createJwt({
    sub: String(CURRENT_USER.id),
    exp: Math.floor(new Date(fixedNow).valueOf() / 1000) + 60 * 60,
    session_id: 'uiux-visual-session',
  })

  await page.addInitScript(({ accessToken, userSummary }) => {
    localStorage.setItem('auth_token', accessToken)
    localStorage.setItem('refresh_token', accessToken)
    localStorage.setItem('current_user_summary', JSON.stringify(userSummary))
    localStorage.removeItem('suspended_refresh_token')
  }, {
    accessToken: token,
    userSummary: CURRENT_USER,
  })
}

async function clearAuthenticatedLayout(page: Page) {
  await page.addInitScript(() => {
    localStorage.removeItem('auth_token')
    localStorage.removeItem('refresh_token')
    localStorage.removeItem('current_user_summary')
    localStorage.removeItem('suspended_refresh_token')
  })
}

async function installApiMocks(page: Page) {
  await page.route('**/api/**', async (route: Route) => {
    const request = route.request()
    const url = new URL(request.url())
    const path = url.pathname
    const method = request.method()

    const json = (body: unknown, status = 200) =>
      route.fulfill({
        status,
        contentType: 'application/json',
        body: JSON.stringify(body),
      })

    if (path === '/api/auth/me') {
      return json(CURRENT_USER)
    }
    if (path === `/api/users-public/${CURRENT_USER.id}`) {
      return json({
        id: CURRENT_USER.id,
        account_name: CURRENT_USER.account_name,
        mobile_number: '09120000000',
        address: 'تهران، خیابان نمونه، پلاک ۱۲',
        created_at: fixedNow,
        trades_count: 0,
        last_seen_at: fixedNow,
      })
    }
    if (path === '/api/invitations/lookup/uiux-baseline') {
      return json({
        valid: true,
        state: 'pending',
        token: 'uiux-baseline-token',
        bot_available: true,
        web_available: true,
        expires_at: null,
      })
    }
    if (path === '/api/config') {
      return json({ bot_username: 'uiux_baseline_bot' })
    }
    if (path === '/api/sessions/verify') {
      return json({ ok: true })
    }
    if (path === '/api/chat/poll') {
      return json({
        conversations_with_unread: [],
        muted_conversation_ids: [],
        unread_chats_count: 0,
        total_unread_mentions: 0,
      })
    }
    if (path === '/api/notifications/' && method === 'GET') {
      return json([])
    }
    if (path === '/api/notifications/mark-all-read') {
      return json({ ok: true })
    }
    if (path === '/api/sessions/active') {
      return json([
        {
          id: 'uiux-session',
          device_name: 'Baseline Browser',
          platform: 'web',
          is_current: true,
          created_at: fixedNow,
          last_seen_at: fixedNow,
        },
      ])
    }
    if (path === '/api/trades/my') {
      return json([])
    }
    if (path === '/api/auth/switchable-users') {
      return json([])
    }
    if (path === '/api/offers/page' && method === 'GET') {
      return json({ items: [], next_cursor: null, has_more: false, page_size: 0 })
    }
    if (path === '/api/offers/my') {
      return json([])
    }
    if (path === '/api/commodities/') {
      return json([{ id: 1, name: 'طلای آب‌شده', aliases: ['آبشده'] }])
    }
    if (path === '/api/trading-settings/') {
      return json({
        offer_min_quantity: 1,
        offer_max_quantity: 1000,
        lot_min_size: 5,
        lot_max_count: 5,
        offer_expiry_minutes: 60,
        invitation_expiry_days: 7,
        market_schedule_enabled: true,
        market_timezone: 'Asia/Tehran',
        market_open_time_local: '10:00',
        market_close_time_local: '18:00',
        market_closed_weekdays: [4],
      })
    }
    if (path === '/api/trading-settings/market-state') {
      return json({
        is_open: true,
        active_web_notice_visible: false,
        offers_since_last_open: 0,
        last_transition_at: null,
        next_transition_at: null,
      })
    }
    if (path === '/api/trading-settings/market-overrides') {
      return json([])
    }
    if (path === '/api/admin-messages/market/current') {
      return json(null)
    }
    if (path === '/api/invitations/pending') {
      return json([])
    }
    if (path === '/api/customers/owner-relations') {
      return json([])
    }
    if (path === '/api/accountants/owner-relations') {
      return json([])
    }
    if (path.startsWith('/api/invitations/') || path.startsWith('/api/register/')) {
      return json({ ok: true })
    }

    return json({})
  })
}

async function gotoRouteWithNavigationRetry(page: Page, path: string) {
  let lastError: unknown = null
  for (let attempt = 0; attempt < 3; attempt += 1) {
    try {
      await page.goto(path, { waitUntil: 'domcontentloaded' })
      return
    } catch (error) {
      lastError = error
      const message = error instanceof Error ? error.message : String(error)
      if (!/interrupted by another navigation|NS_BINDING_ABORTED|NS_ERROR_FAILURE/i.test(message)) {
        throw error
      }
      await page.waitForTimeout(250)
    }
  }
  throw lastError
}

async function expectCriticalA11yBasics(page: Page, label: string) {
  const issues = await page.evaluate(() => {
    const isVisible = (element: HTMLElement) => {
      const style = window.getComputedStyle(element)
      const rect = element.getBoundingClientRect()
      return style.display !== 'none'
        && style.visibility !== 'hidden'
        && Number(style.opacity || '1') > 0
        && rect.width > 0
        && rect.height > 0
    }

    const nameFor = (element: HTMLElement) =>
      [
        element.getAttribute('aria-label'),
        element.getAttribute('title'),
        element.textContent,
      ].join(' ').trim()

    return Array.from(document.querySelectorAll<HTMLElement>('button, a[href], input, textarea, select'))
      .filter(isVisible)
      .filter((element) => !nameFor(element) && element.getAttribute('aria-hidden') !== 'true')
      .slice(0, 10)
      .map((element) => ({
        tag: element.tagName,
        className: element.className.toString(),
      }))
  })

  expect(issues, `${label}: visible interactive controls need an accessible name`).toEqual([])
}

test.describe('Non-messenger visual baseline harness', () => {
  test.skip(!shouldRunBaseline, 'Set UI_UX_BASELINE=1 to capture or compare WebApp UI/UX screenshots.')
  test.use({ timezoneId: 'Asia/Tehran', locale: 'fa-IR' })

  for (const viewport of VIEWPORTS) {
    for (const route of ROUTES) {
      test(`${viewport.label}:${route.label}`, async ({ page }) => {
        await installDeterministicRuntime(page)
        await installApiMocks(page)
        if (route.authenticated) {
          await primeAuthenticatedLayout(page)
        } else {
          await clearAuthenticatedLayout(page)
        }

        await page.setViewportSize({ width: viewport.width, height: viewport.height })
        await gotoRouteWithNavigationRetry(page, route.path)
        await expect(page.locator('#app')).toBeVisible({ timeout: 10_000 })
        await expect(page.locator('html')).toHaveAttribute('data-app-mounted', '1', { timeout: 10_000 })
        await expect(page.locator('#boot-loader')).toBeHidden({ timeout: 10_000 })
        await expect(page.getByText(route.readyText, { exact: false }).first()).toBeVisible({ timeout: 10_000 })
        await expect(page.getByText('در حال بارگذاری', { exact: false }).first()).toBeHidden({ timeout: 10_000 })
        await page.evaluate(async () => {
          await document.fonts?.ready
        })

        if (shouldRunA11ySmoke) {
          await expectCriticalA11yBasics(page, `${viewport.label}:${route.label}`)
        }

        await expect(page).toHaveScreenshot(`${route.label}-${viewport.label}.png`, {
          animations: 'disabled',
          fullPage: true,
          maxDiffPixelRatio: 0.005,
        })
      })
    }
  }
})

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { mount } from '@vue/test-utils'

const shellMocks = vi.hoisted(() => ({
  on: vi.fn(),
  off: vi.fn(),
  connect: vi.fn(),
  sendPresenceUpdate: vi.fn(),
  useNotificationRuntime: vi.fn(),
  initChatUploadBackground: vi.fn(async () => {}),
  hasPendingUploadResumeHint: vi.fn(() => false),
  setUploadResumeHint: vi.fn(),
  initChatDocumentDownloadBackground: vi.fn(async () => {}),
  hasPendingDocumentDownloadResumeHint: vi.fn(() => false),
  setDocumentDownloadResumeHint: vi.fn(),
  initChatFileDebugOverlay: vi.fn(),
  setupExpiryTimer: vi.fn(),
  apiFetch: vi.fn(async () => ({})),
  route: { path: '/' },
}))

vi.mock('../composables/useWebSocket', () => ({
  useWebSocket: () => ({
    on: shellMocks.on,
    off: shellMocks.off,
    connect: shellMocks.connect,
    sendPresenceUpdate: shellMocks.sendPresenceUpdate,
  }),
}))

vi.mock('vue-router', () => ({
  useRoute: () => shellMocks.route,
}))

vi.mock('../composables/useNotificationRuntime', () => ({
  useNotificationRuntime: shellMocks.useNotificationRuntime,
}))

vi.mock('../services/chatTransferResumeHints', () => ({
  hasPendingDocumentDownloadResumeHint: shellMocks.hasPendingDocumentDownloadResumeHint,
  hasPendingUploadResumeHint: shellMocks.hasPendingUploadResumeHint,
  setDocumentDownloadResumeHint: shellMocks.setDocumentDownloadResumeHint,
  setUploadResumeHint: shellMocks.setUploadResumeHint,
}))

vi.mock('../services/chatUploadBackground', () => ({
  initChatUploadBackground: shellMocks.initChatUploadBackground,
}))

vi.mock('../services/chatDocumentDownloadBackground', () => ({
  initChatDocumentDownloadBackground: shellMocks.initChatDocumentDownloadBackground,
}))

vi.mock('../composables/chat/useChatFileHandler', () => ({
  initChatFileDebugOverlay: shellMocks.initChatFileDebugOverlay,
}))

vi.mock('../utils/auth', () => ({
  setupExpiryTimer: shellMocks.setupExpiryTimer,
  apiFetch: shellMocks.apiFetch,
}))

describe('AppAuthenticatedShell.vue', () => {
  beforeEach(() => {
    shellMocks.on.mockReset()
    shellMocks.off.mockReset()
    shellMocks.connect.mockReset()
    shellMocks.sendPresenceUpdate.mockReset()
    shellMocks.useNotificationRuntime.mockReset()
    shellMocks.initChatUploadBackground.mockClear()
    shellMocks.hasPendingUploadResumeHint.mockReset()
    shellMocks.hasPendingUploadResumeHint.mockReturnValue(false)
    shellMocks.setUploadResumeHint.mockReset()
    shellMocks.initChatDocumentDownloadBackground.mockClear()
    shellMocks.hasPendingDocumentDownloadResumeHint.mockReset()
    shellMocks.hasPendingDocumentDownloadResumeHint.mockReturnValue(false)
    shellMocks.setDocumentDownloadResumeHint.mockReset()
    shellMocks.initChatFileDebugOverlay.mockClear()
    shellMocks.setupExpiryTimer.mockClear()
    shellMocks.apiFetch.mockReset()
    shellMocks.apiFetch.mockResolvedValue({})
    shellMocks.route.path = '/'
    Object.defineProperty(document, 'hidden', { configurable: true, value: false })
    localStorage.clear()
  })

  afterEach(() => {
    localStorage.clear()
    delete (window as any).deferredPrompt
  })

  it('skips eager background recovery when no pending transfer hint exists and forwards ensureSessionValidation', async () => {
    localStorage.setItem('auth_token', 'jwt')
    localStorage.setItem('refresh_token', 'refresh-token')
    shellMocks.useNotificationRuntime.mockImplementation(({ ensureSessionValidation }) => {
      ;(shellMocks.useNotificationRuntime as any).capturedEnsure = ensureSessionValidation
    })

    const AppAuthenticatedShell = (await import('./AppAuthenticatedShell.vue')).default
    const wrapper = mount(AppAuthenticatedShell, {
      props: { v2Scope: true },
      global: {
        stubs: {
          BottomNav: true,
          SessionApprovalModal: true,
          AppToasts: true,
        },
      },
    })

    expect(shellMocks.initChatUploadBackground).not.toHaveBeenCalled()
    expect(shellMocks.initChatDocumentDownloadBackground).not.toHaveBeenCalled()
    expect(shellMocks.useNotificationRuntime).toHaveBeenCalledWith({
      connect: shellMocks.connect,
      on: shellMocks.on,
      off: shellMocks.off,
      ensureSessionValidation: expect.any(Function),
    })
    expect(shellMocks.setupExpiryTimer).toHaveBeenCalledTimes(1)
    expect(shellMocks.initChatFileDebugOverlay).toHaveBeenCalledTimes(1)
    expect(shellMocks.on).toHaveBeenCalledWith('ws:reconnect', expect.any(Function))
    expect(shellMocks.sendPresenceUpdate).toHaveBeenCalledWith('/', true)
    expect(wrapper.findComponent({ name: 'SessionApprovalModal' }).props('v2Portal')).toBe(true)
    expect(wrapper.findComponent({ name: 'BottomNav' }).props('v2Scope')).toBe(true)

    const ensureSessionValidation = (shellMocks.useNotificationRuntime as any).capturedEnsure
    await ensureSessionValidation()
    expect(shellMocks.apiFetch).toHaveBeenCalledWith('/api/sessions/verify', {
      method: 'POST',
      body: JSON.stringify({ refresh_token: 'refresh-token' }),
    })

    wrapper.unmount()
    expect(shellMocks.off).toHaveBeenCalledWith('ws:reconnect', expect.any(Function))
    expect(shellMocks.sendPresenceUpdate).toHaveBeenLastCalledWith('/', false)
  }, 15_000)

  it('starts background recovery immediately when a pending transfer hint exists', async () => {
    shellMocks.hasPendingUploadResumeHint.mockReturnValue(true)
    shellMocks.hasPendingDocumentDownloadResumeHint.mockReturnValue(true)

    const AppAuthenticatedShell = (await import('./AppAuthenticatedShell.vue')).default
    mount(AppAuthenticatedShell, {
      global: {
        stubs: {
          BottomNav: true,
          SessionApprovalModal: true,
          AppToasts: true,
        },
      },
    })

    await vi.waitFor(() => {
      expect(shellMocks.initChatUploadBackground).toHaveBeenCalledTimes(1)
      expect(shellMocks.initChatDocumentDownloadBackground).toHaveBeenCalledTimes(1)
    })
  })

  it('keeps security layers but omits BottomNav in focused authenticated mode', async () => {
    const AppAuthenticatedShell = (await import('./AppAuthenticatedShell.vue')).default
    const wrapper = mount(AppAuthenticatedShell, {
      props: { v2Scope: true, showDailyNavigation: false },
      global: {
        stubs: {
          BottomNav: true,
          SessionApprovalModal: true,
          AppToasts: true,
        },
      },
    })

    expect(wrapper.findComponent({ name: 'BottomNav' }).exists()).toBe(false)
    expect(wrapper.findComponent({ name: 'SessionApprovalModal' }).props('v2Portal')).toBe(true)
    expect(wrapper.findComponent({ name: 'AppToasts' }).props('v2Scope')).toBe(true)
  })

  it('skips session verification without a refresh token and swallows verification failures', async () => {
    shellMocks.useNotificationRuntime.mockImplementation(({ ensureSessionValidation }) => {
      ;(shellMocks.useNotificationRuntime as any).capturedEnsure = ensureSessionValidation
    })
    shellMocks.apiFetch.mockRejectedValueOnce(new Error('unauthorized'))

    const AppAuthenticatedShell = (await import('./AppAuthenticatedShell.vue')).default
    mount(AppAuthenticatedShell, {
      global: {
        stubs: {
          BottomNav: true,
          SessionApprovalModal: true,
          AppToasts: true,
        },
      },
    })

    const ensureSessionValidation = (shellMocks.useNotificationRuntime as any).capturedEnsure
    await ensureSessionValidation()
    expect(shellMocks.apiFetch).not.toHaveBeenCalled()

    localStorage.setItem('refresh_token', 'refresh-token')
    await expect(ensureSessionValidation()).resolves.toBeUndefined()
  })
})

/// <reference types="vite/client" />
/// <reference types="vite-plugin-pwa/client" />

/* eslint-disable */
import 'vue-router'
import type { UiRouteShellClass, UiV2Scope } from './router/uiRouteContract'

declare module 'vue-router' {
  interface RouteMeta {
    requiresAuth?: boolean
    requiresAdmin?: boolean
    requiresMarketAccess?: boolean
    requiresOwnerAccess?: boolean
    uiShellClass?: UiRouteShellClass
    uiV2Scope?: UiV2Scope
    uiRouteTestId?: string
  }
}

import { describe, expect, it } from 'vitest'
import {
  buildNotificationTitle,
  createToastNotification,
  getNotificationDisplayKind,
  normalizeAppNotificationPayload,
  normalizeNotificationCategory,
  normalizeNotificationId,
  normalizeNotificationLevel,
  sanitizeNotificationBody,
  sanitizeNotificationTitle,
} from './notifications'

describe('notification type helpers', () => {
  it('normalizes ids, categories, and levels defensively', () => {
    expect(normalizeNotificationId(42)).toBe(42)
    expect(normalizeNotificationId('17')).toBe(17)
    expect(typeof normalizeNotificationId('   ')).toBe('number')

    expect(normalizeNotificationCategory('USER')).toBe('user')
    expect(normalizeNotificationCategory('unknown')).toBe('system')
    expect(normalizeNotificationLevel('WARNING')).toBe('warning')
    expect(normalizeNotificationLevel('unknown')).toBe('info')
  })

  it('fills in notification payload defaults from message/category data', () => {
    const normalized = normalizeAppNotificationPayload({
      id: '88',
      message: 'system body',
      category: 'trade',
      level: 'SUCCESS',
    })

    expect(normalized.id).toBe(88)
    expect(normalized.title).toBe(buildNotificationTitle('trade'))
    expect(normalized.body).toBe('system body')
    expect(normalized.content).toBe('system body')
    expect(normalized.message).toBe('system body')
    expect(normalized.category).toBe('trade')
    expect(normalized.level).toBe('success')
  })

  it('normalizes persisted extra_payload metadata into the same shape as realtime payloads', () => {
    const normalized = normalizeAppNotificationPayload({
      id: 91,
      message: 'trade body',
      category: 'trade',
      extra_payload: {
        route: '/users/19?account_name=ali',
        trade_number: 10025,
        recipient_role: 'offer_owner',
      },
    })

    expect(normalized.route).toBe('/users/19?account_name=ali')
    expect(normalized.trade_number).toBe(10025)
    expect(normalized.recipient_role).toBe('offer_owner')
    expect(normalized.message).toBe('trade body')
  })

  it('removes route and backend metadata from every normalized display body', () => {
    const rawBody = [
      'route: /market',
      'route=/admin',
      '🧭 مسیر: /account',
      'مسیر：/market',
      'backend: iran',
      'backend＝foreign',
      'server: api-01',
      '🏷️ کالا: امام',
      '📝 توضیحات: سالم',
    ].join('\n')
    const normalized = normalizeAppNotificationPayload({ message: rawBody, category: 'trade' })

    expect(normalized.body).toBe('🏷️ کالا: امام\n📝 توضیحات: سالم')
    expect(normalized.content).toBe(normalized.body)
    expect(normalized.message).toBe(normalized.body)
    expect(sanitizeNotificationBody(rawBody)).toBe(normalized.body)
    expect(normalized.body).not.toContain('/market')
    expect(normalized.body).not.toContain('/account')
    expect(normalized.body).not.toContain('iran')
    expect(normalized.body).not.toContain('api-01')
  })

  it('removes metadata separated by every JSON line-break form', () => {
    expect(
      sanitizeNotificationBody(
        'متن سالم\rbackend=iran\rroute=/admin\u2028مسیر：/market\u2029server＝foreign',
      ),
    ).toBe('متن سالم')
  })

  it('replaces hostile metadata titles with the category fallback', () => {
    for (const title of [
      'route: /admin/system',
      'route=/admin/system',
      '🧭 مسیر: /market',
      'مسیر：/market',
      'BACK-END: iran',
      'server: api-01',
    ]) {
      const normalized = normalizeAppNotificationPayload({ title, body: 'متن امن' })
      expect(normalized.title).toBe('پیام مدیریت')
      expect(normalized.title).not.toContain('/')
      expect(normalized.title).not.toContain('iran')
    }
    expect(sanitizeNotificationTitle('route: /market', 'عنوان امن')).toBe('عنوان امن')
  })

  it('creates toast ids and resolves display kinds for chat, system, and level-driven items', () => {
    const toast = createToastNotification({ title: 't', body: 'b' })
    expect(typeof toast.id).toBe('number')
    expect(toast.kind).toBe('app')

    expect(getNotificationDisplayKind({ kind: 'chat' })).toBe('chat')
    expect(getNotificationDisplayKind({ category: 'system' })).toBe('system')
    expect(getNotificationDisplayKind({ category: 'user', level: 'error' })).toBe('error')
    expect(getNotificationDisplayKind({ category: 'user' })).toBe('info')
  })

  it('preserves explicit payload text and supports user titles plus chat-kind toasts', () => {
    const normalized = normalizeAppNotificationPayload({
      id: 'room-alert',
