    fetchMock.mockResolvedValueOnce(makeJsonResponse({ detail: '' }, false, 403) as any)
    await approvalVm.startDevLogin()
    expect(approvalVm.error).toBe('دسترسی مجاز نیست')

    approvalWrapper.unmount()
    wrapper.unmount()
  })

